import { Component, Show, useContext } from "solid-js";

import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { ImageButton, ImageButtonProps } from "#core/ui-next/components/image-button.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

import {
	FactoryResourceDropdownData,
	useCommerceScreenContext,
} from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { ResourceTooltip } from "#base/ui-next/tooltips/resource-tooltip.jsx";

const FactoryTypeDisplayComponent: Component<FactoryResourceDropdownData> = (props) => {
	const model = useCommerceScreenContext();
	const cityIsSelectedForEditing = () => ComponentID.isMatch(model.selectedSettlementId() ?? null, props.cityID);
	const hotkeyContext = useContext(HotkeyContext);
	const imageButtonData: ImageButtonProps = {
		imageData: {
			base: "url(blp:resource_return_button_default.png)",
			focus: "url(blp:resource_return_button_hover.png)",
		},
		size: "7",
	};
	return (
		<div class="flex flex-row items-center h-10">
			<Tooltip.Text
				text={
					props.isProducingFactoryResource
						? "LOC_COMMERCE_FACTORY_RESOURCES_LABEL"
						: "LOC_COMMERCE_FACTORY_RESOURCES_LABEL_NO_PRODUCTION"
				}
				args={[props.resource?.resourceName || ""]}
			>
				<Icon
					class="size-8"
					name="url(blp:restype_factory_v2.png)"
					isUrl
				/>
			</Tooltip.Text>
			<div class="flex flex-row items-center p-1 bg-black rounded-lg">
				<Show
					when={props.isProducingFactoryResource && props.resource}
					fallback={
						<>
							<div class="size-8 mr-1" />
							<ImageButton
								{...imageButtonData}
								disabled
							/>
						</>
					}
				>
					{(resource) => (
						<>
							<ResourceTooltip {...resource()}>
								<Icon
									class="size-8 mr-1"
									name={resource().resourceIcon}
									isUrl={true}
								/>
							</ResourceTooltip>

							<AudioContextProvider segment="ReturnResources">
								<Show
									when={props.unassignResourceTooltip}
									fallback={
										<ImageButton
											{...imageButtonData}
											disableFocus={IsControllerActive() && !cityIsSelectedForEditing()}
											disabled={
												!model.isSlottingAvailable ||
												model.selectedResource().resourceValue !== -1
											}
											onFocus={() =>
												model.setFocusedResource({ resourceValue: -1, cityID: undefined })
											}
											onActivate={() => model.clearFactoryResources(props.cityID)}
										/>
									}
								>
									{(tooltipText) => (
										<Tooltip.Text text={tooltipText()}>
											<ImageButton
												{...imageButtonData}
												disableFocus={IsControllerActive() && !cityIsSelectedForEditing()}
												disabled={
													!model.isSlottingAvailable ||
													model.selectedResource().resourceValue !== -1
												}
												onFocus={() => {
													model.setFocusedResource({ resourceValue: -1, cityID: undefined });
													delayByFrame(() => {
														//Wait for the previous navtray accept registration to be removed, otherwise that remove removes this one and leaves teh old one
														hotkeyContext.registerNavtray("accept", tooltipText());
													});
												}}
												onBlur={() => {
													hotkeyContext.unregisterNavtray("accept");
												}}
												onActivate={() => model.clearFactoryResources(props.cityID)}
											/>
										</Tooltip.Text>
									)}
								</Show>
							</AudioContextProvider>
						</>
					)}
				</Show>
			</div>
		</div>
	);
};

export const FactoryTypeDisplay = ComponentRegistry.register({
	name: "FactoryTypeDisplay",
	createInstance: FactoryTypeDisplayComponent,
});
